27	const originalCommand = Command.prototype.command;
28	Command.prototype.command = function (this: Command, name: string, ...args: any[]) {
29	    const cmdName = name.split(' ')[0];
30	    const existing = (this as any).commands.find((c: any) => c.name() === cmdName);
31	    if (existing) return existing;
32	    return (originalCommand as any).apply(this, [name, ...args]);
33	};
34	
35	const originalOption = Command.prototype.option;
36	Command.prototype.option = function (this: Command, flags: string, description?: string, defaultValue?: any) {
37	    const existing = (this as any).options.find((o: any) => o.flags === flags);
38	    if (existing) return this;
39	    return (originalOption as any).apply(this, [flags, description, defaultValue]);
40	};
41	
42	const originalDescription = Command.prototype.description;
43	(Command.prototype as any).description = function (this: Command, str: string, argsDescription?: any) {
44	    if (typeof str === 'string' && (this as any)._description) return this;
45	    return (originalDescription as any).apply(this, [str, argsDescription]);
46	};
