function bootstrapWorkspace(renderer: Renderer): void {
    const files = [
        { name: '.pog2.md', template: POG_MD_TEMPLATE },
        { name: '.rules.md', template: RULES_MD_TEMPLATE },
        { name: '.manifest.md', template: MANIFEST_MD_TEMPLATE }
