511	        sourceAgent: AgentType = 'unknown'
512	    ): Promise<Result<EngineOutput>> {
513	        
514	        // ─── COGNITIVE IMMUNOLOGY PRE-SCAN ───
515	        const context = [
516	            `Tool: ${toolName}`,
517	            `Source: ${sourceAgent}`,
518	            ...Object.entries(args).map(([k, v]) => {
519	                const val = typeof v === 'object' ? JSON.stringify(v) : String(v);
520	                // Truncate long values to prevent context explosion
521	                return `${k}: ${val.length > 200 ? val.substring(0, 200) + '...' : val}`;
522	            })
523	        ];
524	        
525	        const report = await this.immunology.scan(
526	            context,
527	            sourceAgent,
528	            args['filePath'] as string | undefined
529	        );
530	        
531	        // Record this modification for chain tracing
532	        if (args['filePath']) {
533	            this.immunology.recordAgentModification({
534	                agent: sourceAgent,
535	                file: args['filePath'] as string,
536	                lines: [0, 0], // Will be updated post-execution if file modified
537	                timestamp: Date.now(),
538	                description: `Tool: ${toolName}`
539	            });
540	        }
541	        
542	        // BLOCK: HIGH and CRITICAL
543	        if (report.threatLevel === 'HIGH' || report.threatLevel === 'CRITICAL') {
544	            logger.error({
545	                tool: toolName,
546	                agent: sourceAgent,
547	                threat: report.threatLevel,
548	                reasons: report.reasons,
549	                contextHash: report.contextHash
550	            }, 'COGNITIVE IMMUNOLOGY BLOCK');
551	            
552	            return err({
553	                name: 'Error',
554	                message: `Cognitive Immunology blocked execution. Threat: ${report.threatLevel}. Reasons: ${report.reasons.join('; ')}`,
555	                code: 'IMMUNOLOGY_BLOCK',
556	                report
557	            } as any);
558	        }
559	        
560	        // WARN: MEDIUM — log but continue with sovereign flag
