562	            logger.warn({
563	                tool: toolName,
564	                agent: sourceAgent,
565	                reasons: report.reasons
566	            }, 'COGNITIVE IMMUNOLOGY WARNING');
567	            
568	            // Proceed with caution flag in metadata
569	            (args as any)._immunologyWarning = report.reasons;
570	        }
571	        
